const CAT_TIP={
"Adjectival":"Adjectival endings turn a body-part noun into a describing word — they answer “pertaining to what?”",
"Instrument":"Instrument endings name a device. Spot one and ask: “What gadget is being used?”",
"Procedure":"Procedure endings tell you something was DONE to the patient, usually by a surgeon.",
"Process":"Process endings describe something unfolding over time — building, breaking down or carrying.",
"Direction":"Direction endings point the way — towards a place or drawn towards a target tissue.",
"Symptom":"Symptom endings describe what the patient feels or shows — the clues they report.",
"Function":"Function endings deal with how the body works: sensing, secreting, breathing, digesting, seeing.",
"State":"State endings describe how things stand — a level, tendency or steady condition of the system.",
"Condition":"Condition endings flag that something is wrong or present — a disorder to name and manage.",
"Action":"Action endings are about doing: moving, eating, speaking and coordinating.",
"Structure":"Structure endings name a physical thing you could point to: a cell, a stone, a growth.",
"Compound ending":"Compound endings are two-part power-endings (watch for the double-R “flow family”: -rrhage, -rrhagia, -rrhexis, -rrhoea).",
"Agent":"Agent endings name the culprit substance that does something — kills or produces.",
"Record":"A record ending is the finished output — the tracing or image you file in the notes.",
"Person":"Person endings name a human being — the specialist you would actually meet.",
"Specialty":"Specialty endings name a whole field of medicine or its treatment branch.",
"Test":"Test endings name an examination or measuring process performed on the patient."};

