/* ================================================================
   STATE  (localStorage with safe in-memory fallback)
================================================================ */
const store={ok:true,mem:{},
 get(k){try{return localStorage.getItem(k)}catch(e){this.ok=false;return this.mem[k]||null}},
 set(k,v){try{localStorage.setItem(k,v)}catch(e){this.ok=false;this.mem[k]=v}}};
let S;
try{S=JSON.parse(store.get("suffixQuest_v1")||"null")}catch(e){S=null}
if(!S||typeof S!=="object")S={};
S.xp=S.xp||0;S.viewed=S.viewed||[];S.mastered=S.mastered||[];S.fav=S.fav||[];
S.listened=S.listened||[];S.earned=S.earned||[];S.badges=S.badges||[];
S.bestQuiz=S.bestQuiz||null;S.bestCombo=S.bestCombo||0;S.perfect=S.perfect||false;
S.matchWins=S.matchWins||0;S.fcKnow=S.fcKnow||0;S.quizCorrect=S.quizCorrect||0;S.theme=S.theme||"light";S.introCorrect=S.introCorrect||[];S.introHidden=!!S.introHidden;
const save=()=>store.set("suffixQuest_v1",JSON.stringify(S));
const inSet=(arr,i)=>arr.includes(i);

/* ---------- helpers ---------- */
const $=id=>document.getElementById(id);
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const sample=(a,n)=>shuffle(a).slice(0,n);
const esc=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;");
function toast(msg,ms=2400){const box=$("toasts");while(box.children.length>=2)box.firstChild.remove();const t=document.createElement("div");t.className="toast";t.innerHTML=msg;box.appendChild(t);setTimeout(()=>{t.style.opacity="0";t.style.transition=".4s";setTimeout(()=>t.remove(),420)},ms)}
function confetti(n=44){const em=["🎉","⭐","✨","🎊","💜","🧡","💙","🏆"];for(let i=0;i<n;i++){const s=document.createElement("span");s.className="confetti-bit";s.textContent=em[i%em.length];s.style.left=Math.random()*98+"vw";s.style.top=(-4-Math.random()*8)+"vh";s.style.animationDelay=(Math.random()*.5)+"s";s.style.fontSize=(13+Math.random()*16)+"px";document.body.appendChild(s);setTimeout(()=>s.remove(),2600)}}

/* ================================================================
   XP / LEVELS / BADGES
================================================================ */
const TITLES=["Suffix Scout","Word Explorer","Term Tracker","Clinical Decoder","Suffix Specialist","Terminology Titan","Word Wizard 🧙"];
const levelFrom=xp=>{let l=1,th=80,x=xp;while(x>=th){x-=th;l++;th=Math.round(th*1.45)}return{lvl:l,into:x,need:th}};
let awarding=false;
function addXP(n,why){S.xp+=n;$("hudXp").classList.remove("pulse");void $("hudXp").offsetWidth;$("hudXp").classList.add("pulse");toast(`⭐ +${n} XP — ${why}`,1500);updateHUD();checkBadges();save()}
function earn(key,n,why){if(S.earned.includes(key))return;S.earned.push(key);addXP(n,why)}
const BADGES=[
 {id:"first",icon:"👣",name:"First Steps",desc:"Open your first card pop-up",test:()=>S.viewed.length>=1},
 {id:"intro",icon:"📘",name:"Foundation First",desc:"Score 3/3 in the intro 60-second check",test:()=>(S.introCorrect||[]).length>=3},
 {id:"exp10",icon:"🧭",name:"Explorer",desc:"Open 10 different cards",test:()=>S.viewed.length>=10},
 {id:"exp25",icon:"🗺️",name:"Adventurer",desc:"Open 25 different cards",test:()=>S.viewed.length>=25},
 {id:"half",icon:"⛰️",name:"Halfway Hero",desc:"Open 50 different cards",test:()=>S.viewed.length>=50},
 {id:"all",icon:"👑",name:"Completionist",desc:"Open all 100 cards",test:()=>S.viewed.length>=100},
 {id:"ear10",icon:"👂",name:"Keen Listener",desc:"Listen to 10 suffixes",test:()=>S.listened.length>=10},
 {id:"ear50",icon:"🎧",name:"Audio Ace",desc:"Listen to 50 suffixes",test:()=>S.listened.length>=50},
 {id:"m10",icon:"⭐",name:"Rising Star",desc:"Master 10 suffixes",test:()=>S.mastered.length>=10},
 {id:"m50",icon:"🌟",name:"Master Builder",desc:"Master 50 suffixes",test:()=>S.mastered.length>=50},
 {id:"m100",icon:"💎",name:"Suffix Supreme",desc:"Master all 100 suffixes",test:()=>S.mastered.length>=100},
 {id:"combo",icon:"🔥",name:"On Fire",desc:"Reach a ×5 quiz combo",test:()=>S.bestCombo>=5},
 {id:"quizwhiz",icon:"⚡",name:"Quiz whiz",desc:"Score 80%+ in a Quiz Rush",test:()=>!!S.bestQuiz&&S.bestQuiz.t>0&&(S.bestQuiz.c/S.bestQuiz.t)>=0.8},
 {id:"perfect",icon:"🎯",name:"Perfect Score",desc:"Finish a quiz with zero mistakes",test:()=>S.perfect},
 {id:"match",icon:"🧩",name:"Match Maker",desc:"Complete a Match Game board",test:()=>S.matchWins>=1},
 {id:"flash",icon:"🃏",name:"Flash Master",desc:"Say “I know it!” to 20 flashcards",test:()=>S.fcKnow>=20},
 {id:"xp500",icon:"🚀",name:"XP Legend",desc:"Earn 500 total XP",test:()=>S.xp>=500}
];
function checkBadges(){if(awarding)return;awarding=true;let newOnes=[];BADGES.forEach(b=>{if(!S.badges.includes(b.id)&&b.test()){S.badges.push(b.id);newOnes.push(b)}});awarding=false;if(newOnes.length){save();renderAwards();updateHUD();newOnes.forEach((b,i)=>setTimeout(()=>{toast(`🏆 Badge unlocked: ${b.icon} <b>${b.name}</b> — ${b.desc}`,3600);confetti(36)},i*700))}}
function updateHUD(){const L=levelFrom(S.xp);$("xpNum").textContent=S.xp;$("lvlNum").textContent=L.lvl;$("lvlTitle").textContent=TITLES[Math.min(L.lvl-1,TITLES.length-1)];$("lvlBar").style.width=Math.min(100,L.into/L.need*100)+"%";
 $("seenNum").textContent=S.viewed.length;$("seenBar").style.width=S.viewed.length+"%";
 $("masterNum").textContent=S.mastered.length;$("masterBar").style.width=S.mastered.length+"%";
 $("bestQuiz").textContent=S.bestQuiz?`${S.bestQuiz.c}/${S.bestQuiz.t}`:"—";$("bestCombo").textContent="×"+S.bestCombo;$("badgeCount").textContent=S.badges.length+" / "+BADGES.length}

/* ================================================================
   SPEECH  (Web Speech API)
================================================================ */
let tour={on:false,queue:[],pos:0};
function pickVoice(){const vs=speechSynthesis.getVoices();const sel=$("voiceSel").value;if(sel){const v=vs.find(v=>v.name===sel);if(v)return v}
 return vs.find(v=>/en[-_]GB/i.test(v.lang)&&/female|Libby|Sonia/i.test(v.name))||vs.find(v=>/en[-_]GB/i.test(v.lang))||vs.find(v=>/^en/i.test(v.lang))||vs[0]||null}
function fillVoices(){if(!("speechSynthesis" in window))return;const vs=speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang));const sel=$("voiceSel");const cur=sel.value;sel.innerHTML='<option value="">British English (auto)</option>'+vs.map(v=>`<option value="${esc(v.name)}">${esc(v.name)} (${esc(v.lang)})</option>`).join("");sel.value=cur}
if("speechSynthesis" in window){fillVoices();speechSynthesis.onvoiceschanged=fillVoices}
function speak(text,idx=null,onend=null){
 if(!("speechSynthesis" in window)){toast("🔇 Sorry — speech is not supported in this browser. Try Chrome, Edge or Safari.",3400);if(onend)onend();return}
 speechSynthesis.cancel();
 const u=new SpeechSynthesisUtterance(text);const v=pickVoice();if(v)u.voice=v;u.lang=(v&&v.lang)||"en-GB";u.rate=parseFloat($("rateSel").value)||0.9;
 if(onend)u.onend=onend;u.onerror=()=>{if(onend)onend()};
 speechSynthesis.speak(u);
 if(idx!==null&&!inSet(S.listened,idx)){S.listened.push(idx);save();earn("listen-"+idx,3,"listened to "+DATA[idx][0]);checkBadges()}
}
function stopSpeak(){tour.on=false;$("tourBtn").textContent="▶️ Listen tour";if("speechSynthesis" in window)speechSynthesis.cancel()}
const coreOf=i=>DATA[i][0].replace(/^-/,"");
const cardSpeech=i=>{const d=DATA[i];return `${d[2]}. The suffix ${coreOf(i)} means: ${d[1]}.`};
const fullLesson=i=>{const d=DATA[i];return `${d[2]}. The suffix ${coreOf(i)} means: ${d[1]}. Picture this: ${d[5]} So remember, ${coreOf(i)} means ${d[1]}.`};
$("stopSpeakBtn").onclick=stopSpeak;
$("tourBtn").onclick=()=>{if(tour.on){stopSpeak();toast("⏹ Listen tour stopped");return}
 const list=filtered();if(!list.length)return;tour={on:true,queue:list,pos:0};$("tourBtn").textContent="⏹ Stop tour";
 toast(`🎧 Listen tour: ${list.length} suffix${list.length>1?"es":""} — sit back! Press stop any time.`,3000);
 const next=()=>{if(!tour.on)return;if(tour.pos>=tour.queue.length){tour.on=false;$("tourBtn").textContent="▶️ Listen tour";toast("🎧 Tour finished — brilliant listening!");confetti(30);return}
  const i=tour.queue[tour.pos++];speak(cardSpeech(i),i,()=>setTimeout(next,450))};next()};

