function switchTab(name){document.querySelectorAll(".tab").forEach(t=>t.classList.toggle("on",t.dataset.tab===name));
 document.querySelectorAll(".tabpane").forEach(p=>p.classList.toggle("on",p.id==="pane-"+name));stopSpeak();
 if(name==="awards")renderAwards();if(name==="flash")renderFC();window.scrollTo({top:document.querySelector(".tabs").offsetTop-10,behavior:"smooth"})}
