let fcOrder=[],fcPos=0,fcFlipped=false;
function resetFlash(){fcOrder=filtered();fcPos=0;fcFlipped=false;if($("pane-flash").classList.contains("on"))renderFC()}
function curFC(){return fcOrder.length?fcOrder[fcPos%fcOrder.length]:null}
function renderFC(){if(!fcOrder.length)fcOrder=filtered();const i=curFC();
 if(i===null){$("fcProgress").textContent="No cards in this filter — clear the search to refill the deck.";return}
 const d=DATA[i];const fc=$("fc");fc.style.setProperty("--c",CAT_COLOR[d[3]]);fc.classList.toggle("flipped",fcFlipped);
 $("fcEmoji").textContent=d[4];$("fcEmoji2").textContent=d[4];$("fcSuf").textContent=d[0];
 $("fcExFront").textContent=`${CAT_ICON[d[3]]} ${d[3]} · as in “${d[2]}”`;
 $("fcMean").textContent=d[1];$("fcEx").textContent="e.g. "+d[2];$("fcMnem").textContent="🖼️ "+d[5];
 $("fcProgress").textContent=`Card ${fcPos+1} of ${fcOrder.length} in this deck ${inSet(S.mastered,i)?"· ★ mastered":""}`}
function flipFC(){fcFlipped=!fcFlipped;renderFC()}
$("fc").onclick=flipFC;$("fcFlip").onclick=flipFC;
$("fcNext").onclick=()=>{if(!fcOrder.length)return;fcPos=(fcPos+1)%fcOrder.length;fcFlipped=false;renderFC()};
$("fcPrev").onclick=()=>{if(!fcOrder.length)return;fcPos=(fcPos-1+fcOrder.length)%fcOrder.length;fcFlipped=false;renderFC()};
$("fcShuffle").onclick=()=>{fcOrder=shuffle(fcOrder);fcPos=0;fcFlipped=false;renderFC();toast("🔀 Deck shuffled!")};
$("fcListen").onclick=()=>{const i=curFC();if(i!==null)speak(fcFlipped?fullLesson(i):cardSpeech(i),i)};
$("fcDetail").onclick=()=>{const i=curFC();if(i!==null)openModal(i)};
$("fcKnow").onclick=()=>{const i=curFC();if(i===null)return;S.fcKnow++;if(!inSet(S.mastered,i)){S.mastered.push(i);earn("master-"+i,10,"flashcard mastered "+DATA[i][0])}else toast("✅ Already mastered — nicely consolidated!");
 save();updateHUD();renderGrid();checkBadges();$("fcNext").click()};
$("fcLearning").onclick=()=>{const i=curFC();if(i===null)return;toast("💪 No worries — "+DATA[i][0]+" will come round again. Repetition builds memory!");if(!fcFlipped){fcFlipped=true;renderFC()}else $("fcNext").click()};

/* ================================================================
   QUIZ RUSH
================================================================ */
let quiz=null,quizTimer=null;
function meaningClash(a,b){const x=DATA[a][1].toLowerCase(),y=DATA[b][1].toLowerCase();if(x===y)return true;if(x.startsWith("pertaining")&&y.startsWith("pertaining"))return true;return false}
function distractorIdx(target,n){const sameCat=DATA.map((d,i)=>i).filter(i=>i!==target&&DATA[i][3]===DATA[target][3]&&!meaningClash(i,target));
 const rest=DATA.map((d,i)=>i).filter(i=>i!==target&&DATA[i][3]!==DATA[target][3]&&!meaningClash(i,target));
 let pool=[...shuffle(sameCat),...shuffle(rest)];let out=[];let usedMeaning=new Set();
 for(const i of pool){const m=DATA[i][1].toLowerCase();if(usedMeaning.has(m))continue;if(out.some(o=>meaningClash(o,i)))continue;usedMeaning.add(m);out.push(i);if(out.length>=n)break}
 return out}
function makeQuestion(target){const type=Math.floor(Math.random()*3);const ds=distractorIdx(target,3);const d=DATA[target];
 if(type===0)return{target,sayWord:d[2],html:`What does the suffix <span class="big">${d[0]}</span> mean?<br><small style="color:var(--muted);font-size:.62em">as in “${d[2]}”</small>`,options:shuffle([target,...ds]).map(i=>({i,text:DATA[i][1]})),correct:target};
 if(type===1)return{target,sayWord:d[2],html:`Which suffix means <span class="big">“${esc(d[1])}”</span>?`,options:shuffle([target,...ds]).map(i=>({i,text:DATA[i][0]})),correct:target};
 return{target,sayWord:d[2],html:`Crack the word <span class="big">${esc(d[2])}</span> ${d[4]}<br><small style="color:var(--muted);font-size:.62em">What does its ending <b>${d[0]}</b> tell you?</small>`,options:shuffle([target,...ds]).map(i=>({i,text:DATA[i][1]})),correct:target}}
function startQuiz(forcePool){let pool;
 if(forcePool&&forcePool.length)pool=[...forcePool,...sample(DATA.map((_,i)=>i).filter(i=>!forcePool.includes(i)),9)];
 else{const scope=$("quizScope").value;
  if(scope==="filter")pool=filtered();
  else if(scope==="unmastered")pool=DATA.map((_,i)=>i).filter(i=>!inSet(S.mastered,i));
  else pool=DATA.map((_,i)=>i)}
 if(pool.length<4){toast("⚠️ Not enough suffixes in that selection for a quiz (need 4+). Widen the filter!",3400);return}
 const len=forcePool?Math.min(10,pool.length):Math.min(parseInt($("quizLen").value),pool.length);
 quiz={qs:sample(pool,len).map(makeQuestion),pos:0,score:0,combo:0,bestCombo:0,missed:[],answered:false,time:20};
 $("quizStart").style.display="none";$("quizEnd").style.display="none";$("quizPlay").style.display="block";showQuestion()}
function showQuestion(){clearInterval(quizTimer);const q=quiz.qs[quiz.pos];quiz.answered=false;quiz.time=20;
 $("qProg").textContent=`Question ${quiz.pos+1}/${quiz.qs.length}`;$("qScore").textContent=quiz.score;$("qCombo").textContent=quiz.combo;$("qTime").textContent="20";$("qTimerBar").style.width="100%";
 $("qText").innerHTML=q.html;$("qFeed").className="feedback";$("qFeed").innerHTML="";$("qNext").style.display="none";
 $("qOpts").innerHTML=q.options.map((o,k)=>`<button class="opt" data-k="${k}">${"ABCD"[k]}. ${esc(o.text)}</button>`).join("");
 $("qOpts").querySelectorAll(".opt").forEach(b=>b.onclick=()=>answer(+b.dataset.k));
 quizTimer=setInterval(()=>{quiz.time-=0.25;$("qTime").textContent=Math.max(0,Math.ceil(quiz.time));$("qTimerBar").style.width=Math.max(0,quiz.time/20*100)+"%";if(quiz.time<=0)answer(-1)},250)}
function answer(k){if(!quiz||quiz.answered)return;quiz.answered=true;clearInterval(quizTimer);
 const q=quiz.qs[quiz.pos];const d=DATA[q.target];const right=k>=0&&q.options[k].i===q.correct;
 $("qOpts").querySelectorAll(".opt").forEach((b,j)=>{b.disabled=true;if(q.options[j].i===q.correct)b.classList.add("right");else if(j===k)b.classList.add("wrong")});
 const fb=$("qFeed");
 if(right){quiz.score++;quiz.combo++;quiz.bestCombo=Math.max(quiz.bestCombo,quiz.combo);S.quizCorrect++;S.bestCombo=Math.max(S.bestCombo,quiz.bestCombo);
  let gain=10;if(quiz.combo>0&&quiz.combo%3===0){gain+=5;toast("🔥 Combo ×"+quiz.combo+" — bonus +5 XP!")}
  S.xp+=gain;fb.className="feedback show good";fb.innerHTML=`🎉 <b>Correct!</b> ${d[4]} <b>${d[0]}</b> = ${esc(d[1])} (e.g. ${d[2]}).<br>🖼️ ${esc(d[5])}<br><button class="btn small" style="margin-top:8px" data-oc="speak(cardSpeech(${q.target}),${q.target})">🔊 Hear it</button> <button class="btn small" style="margin-top:8px" data-oc="openModal(${q.target})">🔍 Open pop-up</button>`;
  save();updateHUD()}
 else{quiz.combo=0;quiz.missed.push(q.target);fb.className="feedback show bad";
  fb.innerHTML=`${k<0?"⏰ <b>Out of time!</b>":"❌ <b>Not quite.</b>"} The answer: ${d[4]} <b>${d[0]}</b> = ${esc(d[1])} (e.g. ${d[2]}).<br>🖼️ ${esc(d[5])}<br><button class="btn small" style="margin-top:8px" data-oc="speak(cardSpeech(${q.target}),${q.target})">🔊 Hear it</button> <button class="btn small" style="margin-top:8px" data-oc="openModal(${q.target})">🔍 Learn this card</button>`}
 $("qScore").textContent=quiz.score;$("qCombo").textContent=quiz.combo;
 $("qNext").textContent=quiz.pos>=quiz.qs.length-1?"🏁 See my results":"Next question ➡️";$("qNext").style.display="inline-flex";$("qNext").focus();checkBadges()}
$("qNext").onclick=()=>{quiz.pos++;if(quiz.pos>=quiz.qs.length)endQuiz();else showQuestion()};
$("qListen").onclick=()=>{if(quiz)speak(quiz.qs[quiz.pos].sayWord,quiz.qs[quiz.pos].target)};
$("qQuit").onclick=()=>{clearInterval(quizTimer);quiz=null;$("quizPlay").style.display="none";$("quizStart").style.display="block";toast("Quiz ended — your XP so far is saved ⭐")};
$("quizGo").onclick=()=>startQuiz();
$("quizAgain").onclick=()=>startQuiz();
$("quizToCards").onclick=()=>switchTab("explore");
function endQuiz(){clearInterval(quizTimer);const c=quiz.score,t=quiz.qs.length,pct=Math.round(c/t*100);
 if(!S.bestQuiz||(c/t)>(S.bestQuiz.c/S.bestQuiz.t))S.bestQuiz={c,t};
 if(c===t)S.perfect=true;save();updateHUD();checkBadges();
 $("quizPlay").style.display="none";$("quizEnd").style.display="block";
 $("endScore").textContent=`${c}/${t}`;
 $("endEmoji").textContent=pct===100?"👑🏆":pct>=80?"🏆":pct>=60?"🎉":pct>=40?"💪":"🌱";
 $("endTitle").textContent=pct===100?"PERFECT! Suffix royalty! 👑":pct>=80?"Outstanding decoding!":pct>=60?"Great work — nearly there!":pct>=40?"Good effort — keep practising!":"Every master was once a beginner!";
 $("endSub").textContent=`You scored ${pct}% · Best combo 🔥 ×${quiz.bestCombo} · Total XP now ${S.xp}`;
 $("quizReview").innerHTML=quiz.missed.length?`<h3>🎯 Mission: conquer these ${quiz.missed.length} — tap to learn them now</h3>`+[...new Set(quiz.missed)].map(i=>`<div class="review-item"><span>${DATA[i][4]} <b>${DATA[i][0]}</b> = ${esc(DATA[i][1])} <small style="color:var(--muted)">(${DATA[i][2]})</small></span><span><button class="btn small" data-oc="speak(cardSpeech(${i}),${i})">🔊</button> <button class="btn small primary" data-oc="openModal(${i})">🔍 Learn</button></span></div>`).join(""):`<p class="progress-txt">✨ Flawless — nothing missed! Try the 20-question boss level. 👹</p>`;
 if(pct>=60)confetti(pct===100?80:44);quiz=null}

/* ================================================================
   MATCH GAME
================================================================ */
let match=null,matchTimer=null,selLeft=null,selRight=null;
function newMatch(){clearInterval(matchTimer);const n=parseInt($("matchPairs").value);
 let pool=shuffle(DATA.map((_,i)=>i));let chosen=[];let usedM=new Set();
 for(const i of pool){const m=DATA[i][1].toLowerCase();const fam=m.startsWith("pertaining")?"pertaining":m;if(usedM.has(fam))continue;if(chosen.some(c=>meaningClash(c,i)))continue;usedM.add(fam);chosen.push(i);if(chosen.length>=n)break}
 match={pairs:chosen,done:new Set(),miss:0,secs:0};selLeft=null;selRight=null;
 $("mDone").textContent="0/"+n;$("mMiss").textContent="0";$("mTime").textContent="0";$("matchMsg").textContent="🎯 Tap a suffix, then tap its meaning!";
 $("matchLeft").innerHTML=shuffle(chosen).map(i=>`<button class="tile" data-side="L" data-i="${i}">${DATA[i][4]} ${DATA[i][0]}</button>`).join("");
 $("matchRight").innerHTML=shuffle(chosen).map(i=>`<button class="tile" data-side="R" data-i="${i}">${esc(DATA[i][1])}</button>`).join("");
 document.querySelectorAll(".tile").forEach(t=>t.onclick=()=>tileClick(t));
 matchTimer=setInterval(()=>{if(match){match.secs++;$("mTime").textContent=match.secs}},1000)}
function tileClick(t){if(!match||t.disabled)return;const i=+t.dataset.i;
 if(t.dataset.side==="L"){document.querySelectorAll('.tile[data-side="L"]').forEach(x=>x.classList.remove("sel"));selLeft={i,el:t};t.classList.add("sel");speak(DATA[i][2],null)}
 else{document.querySelectorAll('.tile[data-side="R"]').forEach(x=>x.classList.remove("sel"));selRight={i,el:t};t.classList.add("sel")}
 if(selLeft&&selRight){const L=selLeft,R=selRight;selLeft=null;selRight=null;
  if(L.i===R.i){[L.el,R.el].forEach(el=>{el.classList.remove("sel");el.classList.add("done");el.disabled=true});match.done.add(L.i);S.xp+=10;
   $("mDone").textContent=match.done.size+"/"+match.pairs.length;updateHUD();save();
   toast(`✅ +10 XP — ${DATA[L.i][0]} = ${DATA[L.i][1]} (${DATA[L.i][2]})`,1600);speak(cardSpeech(L.i),L.i);
   if(match.done.size===match.pairs.length){clearInterval(matchTimer);S.matchWins++;S.xp+=30;save();updateHUD();checkBadges();confetti(70);
    $("matchMsg").innerHTML=`🏆 <b>Board complete in ${match.secs}s with ${match.miss} miss${match.miss===1?"":"es"}! +30 XP bonus!</b> Press “New game” for fresh tiles.`}
   else $("matchMsg").textContent="✅ Match! "+(match.pairs.length-match.done.size)+" to go…"}
  else{match.miss++;$("mMiss").textContent=match.miss;[L.el,R.el].forEach(el=>{el.classList.remove("sel");el.classList.add("nope")});setTimeout(()=>[L.el,R.el].forEach(el=>el.classList.remove("nope")),450);
   $("matchMsg").textContent=`❌ Not a pair — ${DATA[L.i][4]} ${DATA[L.i][0]} goes with “${DATA[L.i][1]}”, as in ${DATA[L.i][2]}. Try again!`}}}
$("matchNew").onclick=newMatch;

/* ================================================================
   AWARDS PAGE
================================================================ */
function renderAwards(){$("badgeGrid").innerHTML=BADGES.map(b=>{const got=S.badges.includes(b.id);
 return `<div class="badge ${got?"got":"locked"}"><div class="bi">${got?b.icon:"🔒"}</div><b>${b.name}</b><small>${b.desc}</small><small>${got?"✅ Unlocked":"Keep playing…"}</small></div>`}).join("");
 $("catBars").innerHTML=CATS.slice(1).map(c=>{const total=catCount(c);const got=DATA.filter((d,i)=>d[3]===c&&inSet(S.mastered,i)).length;const seen=DATA.filter((d,i)=>d[3]===c&&inSet(S.viewed,i)).length;
  return `<div class="catbar"><span>${CAT_ICON[c]} ${c}</span><span class="bar" style="margin:0"><i style="width:${total?got/total*100:0}%;background:${CAT_COLOR[c]}"></i></span><span>★ ${got}/${total} <small style="color:var(--muted)">(👀${seen})</small></span></div>`}).join("")}
$("printBtn").onclick=()=>{switchTab("explore");clearFilters();setTimeout(()=>window.print(),350)};
$("resetBtn").onclick=()=>{if(!confirm("Reset ALL progress (XP, mastered cards, badges)? This cannot be undone."))return;
 S={xp:0,viewed:[],mastered:[],fav:[],listened:[],earned:[],badges:[],bestQuiz:null,bestCombo:0,perfect:false,matchWins:0,fcKnow:0,quizCorrect:0,introCorrect:[],introHidden:false,theme:document.documentElement.dataset.theme||"light"};
 save();updateHUD();renderGrid();renderAwards();resetFlash();renderIntroCheck();applyIntroVis();toast("🗑️ Progress reset — fresh quest begins!")};


/* ================================================================
   INTERACTIVE INTRO — WHAT IS A SUFFIX?
================================================================ */
/* ---- 1 · Word train ---- */
const PART_INFO={
 prefix:"🔵 <b>PREFIX (optional starter):</b> sits at the front and fine-tunes the word — how much, how fast, where or when. <b>brady-</b> = slow. Not every word has one.",
 root:"🟢 <b>ROOT (the body part):</b> the core of the word. <b>cardi</b> = heart. Roots answer the question: <i>which part of the body are we talking about?</i>",
 suffix:"⭐ <b>SUFFIX (the ending — the star of this course):</b> try checking it <b>first</b>. <b>-ia</b> = a state or condition. The suffix tells you what kind of word this is: a condition, a procedure, a test, a person… Change the suffix and you change the whole meaning, even with the same body part."
};
function setPart(k){document.querySelectorAll(".train-part").forEach(b=>b.classList.toggle("sel",b.dataset.part===k));$("partExplain").innerHTML=PART_INFO[k]}
document.querySelectorAll(".train-part").forEach(b=>b.onclick=()=>setPart(b.dataset.part));
$("anatomyListen").onclick=()=>speak("bradycardia. brady means slow. cardi means heart. And the suffix ia means a state or condition. So: the state of a slow heartbeat.",idxOfSuffix("-ia"));
$("anatomyCard").onclick=()=>openModal(idxOfSuffix("-ia"));

/* ---- 2 · Read the ending first (stepper) ---- */
const DEC_STEPS=[
 {seg:null,text:"👀 <b>Meet the word: HYPERGLYCAEMIA.</b> It looks long, but it is only 3 small pieces joined together. Press <b>Next step</b> and we will read it like a clinician — starting at the END."},
 {seg:"s",text:"① <b>ENDING FIRST → -aemia</b> = <i>blood condition</i>. Instantly you know this word is about something in the <b>blood</b>. (This is why suffixes come first!)"},
 {seg:"p",text:"② <b>Now the start → hyper-</b> = <i>excessive / too much</i>. So there is too much of something in the blood…"},
 {seg:"r",text:"③ <b>Then the middle → glyc-</b> = <i>sugar (glucose)</i>. The thing in excess is sugar."},
 {seg:"all",text:"🏁 <b>Put it together:</b> excessive + sugar + blood condition = <b>too much sugar in the blood</b>. You just decoded a 14-letter medical word in 3 moves. That is the method for every card below!"}
];
let decPos=0;
const SEGCLASS={p:"lit-p",r:"lit-r",s:"lit-s"};
function renderDecode(){const st=DEC_STEPS[decPos];
 document.querySelectorAll(".decode-word .seg").forEach(el=>{el.classList.remove("dim","lit-p","lit-r","lit-s");
  if(st.seg==="all")el.classList.add(SEGCLASS[el.dataset.seg]);
  else if(st.seg){if(el.dataset.seg===st.seg)el.classList.add(SEGCLASS[st.seg]);else el.classList.add("dim")}});
 $("decodeText").innerHTML=st.text;
 $("decCount").textContent=decPos===0?"Start":"Step "+decPos+" of 4";
 $("decPrev").disabled=decPos===0;
 $("decNext").textContent=decPos===DEC_STEPS.length-1?"↺ Start again":"Next step ▶";
 $("decDots").innerHTML=DEC_STEPS.map((_,k)=>`<button class="dot${k===decPos?" on":""}" data-k="${k}" aria-label="Go to step ${k}"></button>`).join("");
 $("decDots").querySelectorAll(".dot").forEach(d=>d.onclick=()=>{decPos=+d.dataset.k;renderDecode()});
 if(decPos===DEC_STEPS.length-1)earn("intro-decode",5,"decoded hyperglycaemia step by step")}
$("decNext").onclick=()=>{decPos=decPos>=DEC_STEPS.length-1?0:decPos+1;renderDecode()};
$("decPrev").onclick=()=>{if(decPos>0){decPos--;renderDecode()}};
$("decodeListen").onclick=()=>speak("hyperglycaemia. hyper means excessive. glyc means sugar. aemia means a blood condition. Too much sugar in the blood.",idxOfSuffix("-aemia"));
$("decodeCard").onclick=()=>openModal(idxOfSuffix("-aemia"));

/* ---- 3 · Word-Builder Lab ---- */
const ROOTS=[["cardi","cardio","heart","🫀"],["gastr","gastro","stomach","🍽️"],["neur","neuro","nerve","⚡"],["hepat","hepato","liver","🟤"],["arthr","arthro","joint","🦴"]];
const BUILD_SUF=[
 {s:"-itis",make:r=>"inflammation of the "+r},{s:"-algia",make:r=>"pain in the "+r},
 {s:"-megaly",make:r=>"enlargement of the "+r},{s:"-pathy",make:r=>"disease of the "+r},
 {s:"-logy",make:r=>"the study and specialty of the "+r},{s:"-logist",make:r=>"a specialist in the "+r},
 {s:"-ectomy",make:r=>"surgical removal of the "+r+" (or part of it)"},{s:"-scopy",make:r=>"visual examination inside the "+r}];
let bRoot=1,bSuf=0;
function builtNow(){const R=ROOTS[bRoot],B=BUILD_SUF[bSuf],idx=idxOfSuffix(B.s),core=B.s.slice(1);
 const stem=/^[aeiou]/.test(core)?R[0]:R[1];
 return{R,B,idx,stem,core,word:stem+core,meaning:B.make(R[2])}}
function renderBuilder(){const now=builtNow();
 $("rootPicks").innerHTML=ROOTS.map((r,k)=>`<button class="pick${k===bRoot?" on":""}" data-k="${k}">${r[3]} ${r[0]}<small>${r[2]}</small></button>`).join("");
 $("sufPicks").innerHTML=BUILD_SUF.map((b,k)=>{const i=idxOfSuffix(b.s);return `<button class="pick sufpick${k===bSuf?" on":""}" data-k="${k}">${DATA[i][4]} ${b.s}<small>${esc(DATA[i][1])}</small></button>`}).join("");
 $("rootPicks").querySelectorAll(".pick").forEach(b=>b.onclick=()=>{bRoot=+b.dataset.k;renderBuilder();earn("intro-builder",5,"built a word in the Word-Builder Lab")});
 $("sufPicks").querySelectorAll(".pick").forEach(b=>b.onclick=()=>{bSuf=+b.dataset.k;renderBuilder();earn("intro-builder",5,"built a word in the Word-Builder Lab")});
 $("builtWord").innerHTML=`<span class="brt">${now.stem}</span><span class="bsf">${now.core}</span>`;
 $("builtMean").textContent="= "+now.meaning.charAt(0).toUpperCase()+now.meaning.slice(1)+".";
 $("builtMeta").textContent=`${now.R[3]} Root “${now.R[0]}” = ${now.R[2]}  ·  Suffix ${now.B.s} (${DATA[now.idx][3]}) = ${DATA[now.idx][1]}`}
$("builtListen").onclick=()=>{const n=builtNow();speak(`${n.word}. That means: ${n.meaning}.`,n.idx)};
$("builtCard").onclick=()=>openModal(builtNow().idx);
$("builtRandom").onclick=()=>{let r,sf;do{r=Math.floor(Math.random()*ROOTS.length);sf=Math.floor(Math.random()*BUILD_SUF.length)}while(r===bRoot&&sf===bSuf);bRoot=r;bSuf=sf;renderBuilder();earn("intro-builder",5,"built a word in the Word-Builder Lab")};

/* ---- 4 · The 5 big jobs ---- */
const JOBS=[
 {cat:"Condition",icon:"🩺",label:"Condition",text:"Something is <b>wrong or present</b> in the body. In a diagnosis list, these endings name the problem itself.",ex:["-itis","-osis","-pathy"]},
 {cat:"Procedure",icon:"🏥",label:"Procedure",text:"Something was <b>done to the patient</b> — cut, removed, repaired or opened. In theatre notes, the suffix tells you exactly what the surgeon did.",ex:["-ectomy","-plasty","-ostomy"]},
 {cat:"Test",icon:"🧪",label:"Test & record",text:"An <b>examination or its output</b>: the look, the measurement, or the tracing filed in the notes.",ex:["-scopy","-graphy","-gram"]},
 {cat:"Person",icon:"👩‍⚕️",label:"Person & specialty",text:"A <b>human being or their field</b>. Remember the pair: the <b>-logist</b> is the person you meet; <b>-logy</b> is what they studied.",ex:["-logist","-iatrist","-logy"]},
 {cat:"Adjectival",icon:"🏷️",label:"Describing word",text:"Turns a body part into an <b>adjective</b> meaning “pertaining to…”. The hardest-working little labels in medicine.",ex:["-ac","-al","-ic"]}];
let jobSel=0;
function renderJobs(){const j=JOBS[jobSel];
 $("jobPicks").innerHTML=JOBS.map((x,k)=>`<button class="pick${k===jobSel?" on":""}" data-k="${k}">${x.icon} ${x.label}</button>`).join("");
 $("jobPicks").querySelectorAll(".pick").forEach(b=>b.onclick=()=>{jobSel=+b.dataset.k;renderJobs()});
 $("jobExplain").innerHTML=`${j.icon} <b>${j.label} endings</b> — ${j.text}<br><span style="color:var(--muted)">${catCount(j.cat)} of your 100 cards do this job.</span>`;
 $("jobExamples").innerHTML=j.ex.map(sx=>{const i=idxOfSuffix(sx);return `<button class="pick" data-open="${i}">${DATA[i][4]} ${sx}<small>${esc(DATA[i][1])} · ${DATA[i][2]}</small></button>`}).join("");
 $("jobExamples").querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>openModal(+b.dataset.open))}
function showCategory(cat){switchTab("explore");activeCat=cat;query="";$("search").value="";renderPills();renderGrid();resetFlash();
 setTimeout(()=>$("grid").scrollIntoView({behavior:"smooth",block:"start"}),90);
 toast(`${CAT_ICON[cat]} Showing the ${cat} cards — ${catCount(cat)} to conquer!`)}
$("jobGo").onclick=()=>showCategory(JOBS[jobSel].cat);

/* ---- 5 · Safety-spot tiles ---- */
const CONTRAST={"-ectomy":"✂️ CUT <b>OUT</b> — removed for good","-otomy":"🔪 CUT <b>INTO</b> — usually closed again","-ostomy":"🕳️ A new <b>OPENING</b> is made","-gram":"📄 The finished <b>RECORD</b>","-graph":"🖨️ The recording <b>MACHINE</b>","-graphy":"📸 The imaging <b>PROCESS / TEST</b>"};
function renderMini(){const list=["-ectomy","-otomy","-ostomy","-gram","-graph","-graphy"];
 $("miniTiles").innerHTML=list.map(sx=>{const i=idxOfSuffix(sx);const d=DATA[i];
  return `<div class="mini-tile" role="button" tabindex="0" data-tile="${i}" aria-label="Reveal ${sx}"><span style="font-size:26px">${d[4]}</span><span class="ms">${sx}</span><span class="tap-hint">👆 Tap to reveal</span><span class="mm">${CONTRAST[sx]}<br><i>${esc(d[1])}</i><br>e.g. <b>${d[2]}</b><br><button class="btn small" style="margin-top:7px" data-open="${i}">🎴 Full card</button></span></div>`}).join("");
 $("miniTiles").querySelectorAll(".mini-tile").forEach(t=>{const flip=()=>{t.classList.toggle("revealed");
   if([...$("miniTiles").querySelectorAll(".mini-tile")].every(x=>x.classList.contains("revealed")))earn("intro-mini",5,"revealed all 6 safety endings")};
  t.onclick=e=>{if(e.target.closest("[data-open]"))return;flip()};
  t.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();flip()}}});
 $("miniTiles").querySelectorAll("[data-open]").forEach(b=>b.onclick=e=>{e.stopPropagation();openModal(+b.dataset.open)})}

/* ---- 6 · 60-second check ---- */
const CHECK=[
 {q:"1) In <b>gastritis</b>, the ending <b>-itis</b> tells you the stomach is…",opts:["🔥 inflamed","✂️ removed","📏 being measured"],a:0,s:"-itis",why:"✅ <b>-itis = inflammation.</b> gastr (stomach) + itis → an inflamed stomach lining."},
 {q:"2) A <b>cardiologist</b> is…",opts:["📈 a heart tracing","👨‍⚕️ a heart specialist (a person)","📚 the study of the heart"],a:1,s:"-logist",why:"✅ <b>-logist = the specialist PERSON.</b> (-logy would be the study; -gram would be the tracing.)"},
 {q:"3) After an <b>appendicectomy</b>, the appendix has been…",opts:["👀 only looked at","🕳️ given a new opening","✂️ surgically removed"],a:2,s:"-ectomy",why:"✅ <b>-ectomy = surgical removal.</b> Think EXIT-ectomy — it left the body!"}];
function renderIntroCheck(){const done=S.introCorrect||[];
 $("checkScore").textContent=done.length+"/3";
 $("checkDone").classList.toggle("show",done.length>=3);
 $("introCheck").innerHTML=CHECK.map((c,qi)=>{const got=done.includes(qi);
  return `<div class="check-q"><div class="qq">${c.q}</div><div class="check-opts">${c.opts.map((o,oi)=>`<button class="check-opt${got&&oi===c.a?" right":""}" data-q="${qi}" data-o="${oi}" ${got?"disabled":""}>${o}</button>`).join("")}</div><div class="check-fb${got?" show":""}" data-fb="${qi}">${got?c.why:""}</div></div>`}).join("");
 $("introCheck").querySelectorAll(".check-opt").forEach(b=>b.onclick=()=>{const qi=+b.dataset.q,oi=+b.dataset.o,c=CHECK[qi],fb=document.querySelector(`[data-fb="${qi}"]`);
  if(oi===c.a){if(!S.introCorrect.includes(qi))S.introCorrect.push(qi);save();earn("intro-check-"+qi,5,"answered an intro-check question");renderIntroCheck();
   if(S.introCorrect.length>=3){confetti(50);checkBadges()}speak(DATA[idxOfSuffix(c.s)][2],idxOfSuffix(c.s))}
  else{b.classList.add("wrong");b.disabled=true;fb.className="check-fb show";fb.innerHTML="🤔 Not quite — look at the <b>ending</b> of the word and try another option. You have got this!"}})}
/* ---- toggle + shortcuts ---- */
function applyIntroVis(){const hide=!!S.introHidden;$("introBody").style.display=hide?"none":"";
 $("introToggle").textContent=hide?"Show intro ▾":"Hide intro ▴";$("introToggle").setAttribute("aria-expanded",String(!hide))}
$("introToggle").onclick=()=>{S.introHidden=!S.introHidden;save();applyIntroVis()};
$("heroIntro").onclick=()=>{S.introHidden=false;save();applyIntroVis();$("introSection").scrollIntoView({behavior:"smooth",block:"start"})};
$("introToCards").onclick=()=>{switchTab("explore");setTimeout(()=>$("grid").scrollIntoView({behavior:"smooth",block:"start"}),90)};
$("introToQuiz").onclick=()=>switchTab("quiz");
function initIntro(){setPart("suffix");renderDecode();renderBuilder();renderJobs();renderMini();renderIntroCheck();applyIntroVis()}
initIntro();

