function applyTheme(t){if(t==="dark")document.documentElement.setAttribute("data-theme","dark");else document.documentElement.removeAttribute("data-theme");$("themeBtn").textContent=t==="dark"?"☀️ Light mode":"🌙 Dark mode"}
$("themeBtn").onclick=()=>{S.theme=S.theme==="dark"?"light":"dark";applyTheme(S.theme);save()};
applyTheme(S.theme);renderPills();renderGrid();updateHUD();renderAwards();resetFlash();checkBadges();
setTimeout(()=>{if(S.viewed.length===0&&(S.introCorrect||[]).length<3)toast("👋 Welcome! Start with the 📘 <b>2-minute suffix intro</b> below — build a word, pass the 60-second check, then conquer the 100 cards!",5200)},700);
